import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip,
  useMap
} from "react-leaflet";
import { useEffect, useState } from "react";
import axios from "axios";
import L from "leaflet";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip as ChartTooltip
} from "recharts";

// 🔥 Fix marker icons
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

// 🗺️ Fit bounds
function FitBounds({ path }) {
  const map = useMap();

  useEffect(() => {
    if (path.length > 1) {
      map.fitBounds(path.map(p => [p.lat, p.lon]), {
        padding: [50, 50]
      });
    }
  }, [path, map]);

  return null;
}

function App() {
  const [fullPath, setFullPath] = useState([]);
  const [path, setPath] = useState([]);
  const [latest, setLatest] = useState(null);
  const [isReplayDone, setIsReplayDone] = useState(false);

  // 🚀 Fetch initial data
  useEffect(() => {
    fetchInitialData();
  }, []);

  const fetchInitialData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path");

      const formatted = res.data.map((d, i) => ({
        lat: d.location.coordinates[1],
        lon: d.location.coordinates[0],
        alt: d.alt,
        index: i
      }));

      setFullPath(formatted);
    } catch (err) {
      console.error(err);
    }
  };

  // 🎬 Replay animation
  useEffect(() => {
    if (fullPath.length === 0) return;

    let index = 0;

    const interval = setInterval(() => {
      if (index >= fullPath.length) {
        clearInterval(interval);
        setIsReplayDone(true);
        return;
      }

      setPath(fullPath.slice(0, index + 1));
      index++;
    }, 200);

    return () => clearInterval(interval);
  }, [fullPath]);

  // 🚁 Live tracking
  useEffect(() => {
    if (!isReplayDone) return;

    const interval = setInterval(fetchLiveData, 3000);
    return () => clearInterval(interval);
  }, [isReplayDone]);

  const fetchLiveData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/latest");

      if (res.data?.location) {
        const newPoint = {
          lat: res.data.location.coordinates[1],
          lon: res.data.location.coordinates[0],
          alt: res.data.alt,
          index: path.length
        };

setPath(prev => {
  const updated = [...prev, newPoint];

  // 🔥 keep only last 500 points
  if (updated.length > 500) {
    return updated.slice(-500);
  }

  return updated;
});
        setLatest(res.data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="dashboard">
      <h2>🚁 Drone Flight Visualization</h2>

      {/* 📊 Metrics */}
      {latest && (
        <div className="metrics">
          <p>Altitude: {latest.alt?.toFixed(2)} m</p>
          <p>Voltage: {latest.voltage}</p>
          <p>Satellites: {latest.sats}</p>
          <p>GPS: {latest.gps_fix}</p>
        </div>
      )}

      {/* 🗺️ MAP */}
      <MapContainer center={[12.9716, 77.5946]} zoom={18}>
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {/* 🔵 Path */}
        <Polyline
          positions={path.map(p => [p.lat, p.lon])}
          color="cyan"
        />

        {/* 📍 Moving Drone */}
        {path.length > 0 && (
          <Marker position={[path[path.length - 1].lat, path[path.length - 1].lon]}>
            <Tooltip direction="top" offset={[0, -10]} opacity={1} permanent>
              Alt: {path[path.length - 1].alt?.toFixed(2)} m
            </Tooltip>
          </Marker>
        )}

        {/* 📌 Altitude markers along path */}
        {path.map((p, i) =>
          i % 15 === 0 ? (
            <Marker key={i} position={[p.lat, p.lon]}>
              <Tooltip>{p.alt?.toFixed(1)} m</Tooltip>
            </Marker>
          ) : null
        )}

        <FitBounds path={fullPath} />
      </MapContainer>

      {/* 📈 ALTITUDE GRAPH */}
      <div className="chart">
        <h3>📈 Altitude Profile</h3>
        <LineChart width={600} height={200} data={path}>
          <XAxis dataKey="index" stroke="#fff" />
          <YAxis stroke="#fff" />
          <ChartTooltip />
          <Line type="monotone" dataKey="alt" stroke="#00ffcc" />
        </LineChart>
      </div>
    </div>
  );
}

export default App;
